export function clampInteger(value, fallback, min, max) {
  // Attempt to parse the value as a base-10 integer.
  let parsed;
  if (typeof value === 'number') {
    parsed = Math.trunc(value);
  } else if (typeof value === 'string') {
    // Remove surrounding whitespace.
    const trimmed = value.trim();
    if (trimmed === '') {
      return fallback;
    }
    // Ensure the string represents a valid integer in base-10.
    // Use regex to detect optional sign and digits only.
    if (/^[+-]?\d+$/.test(trimmed)) {
      parsed = parseInt(trimmed, 10);
    } else {
      return fallback;
    }
  } else {
    return fallback;
  }

  // Ensure parsed is a finite integer.
  if (!Number.isFinite(parsed)) return fallback;

  // Clamp the value inclusively between min and max.
  if (parsed < min) return min;
  if (parsed > max) return max;
  return parsed;
}

