import path from 'node:path';

/**
 * Resolve a relative path below the workspace root and return the absolute result as a string.
 *
 * @param {string} root - The workspace root path.
 * @param {string} value - The path to resolve. Must be relative and not escape the root.
 * @returns {string} The absolute path.
 * @throws {Error} If the path is absolute or escapes the root.
 */
export function resolveRelative(root, value) {
  // Reject absolute paths immediately
  if (path.isAbsolute(value)) {
    throw new Error(`Path escapes the workspace: ${value} (absolute path)`);
  }

  // Compute the relative path from root to value
  const abs = path.resolve(root, value);
  // Compute relative path from root to the resolved absolute path
  const rel = path.relative(root, abs);
  // If the relative path starts with '..', the target escapes the root
  if (rel === '..' || rel.startsWith(`..${path.sep}`)) {
    throw new Error(`Path escapes the workspace: ${value}`);
  }
  return abs;
}

import assert from 'node:assert';
import { resolveRelative } from '../src/lib.mjs';
import path from 'node:path';

const root = '/workspace';

// Helper to normalize expected path using path.resolve
const expected = (rel) => path.resolve(root, rel);

// 1. Simple relative path inside root
assert.strictEqual(resolveRelative(root, 'folder/file.txt'), expected('folder/file.txt'));

// 2. Path with ./ segment
assert.strictEqual(resolveRelative(root, './folder2/file.md'), expected('folder2/file.md'));

// 3. Path with .. that stays inside root
assert.strictEqual(resolveRelative(root, 'folder/../file.js'), expected('file.js'));

// 4. Path that escapes via leading ..
let err;
try {
  resolveRelative(root, '../secret');
} catch (e) {
  err = e;
}
assert.ok(err, 'Expected error for escaping path');
assert.match(err.message, /escapes/);

// 5. Absolute path
err = undefined;
try {
  resolveRelative(root, '/etc/passwd');
} catch (e) {
  err = e;
}
assert.ok(err, 'Expected error for absolute path');
assert.match(err.message, /escapes/);

// 6. Empty path 
assert.strictEqual(resolveRelative(root, ''), expected(''));

console.log('All tests passed');
